UPDATE assessment_criteria SET test_protocol_json='{"protocolVersion":"pilot-v1","station":"发球与接发组合站","purpose":"观察能否合法发球、稳定把球送入比赛并完成接发后的前移准备","setup":"标准双打场地；同一测试者/喂球者；记录球型号、场地和风况；左右发球区均观察","procedure":["完成统一热身后，从左右发球区交替发球","接发者在底线后接同一测试者发球，按自然回合节奏完成接发","观察者记录发球合法性、接发深度、击球后是否及时前移并恢复平衡"],"valid_trial":"球已按测试任务进入可判断的发球/接发情境；喂球明显偏离预定区域、外部干扰或安全中断时标记无效并注明原因","record_fields":["发球动作与合法性观察","落点区域（左/中/右、短/深）","接发质量与回球深度","接发后前移启动与平衡","无效尝试及原因"],"safety_stop":"出现疼痛、眩晕、明显疲劳或场地湿滑立即停止","adaptations":"青少年可降低喂球速度并延长间歇；常青学员可降低移动覆盖要求但不降低规则要求；适配后必须记录，不能与标准条件成绩直接混比","pilot":"先由两名教练独立观察同一组表现，比较对合法性、深度和前移动作的判读一致性；试测后再确定尝试数与有效球定义","trialCount":"由教练试测校准后确定","passThreshold":null,"decisionRule":"本协议为试测稿；不得据此自动晋级"}', rubric_json='{"scale":"0-4","levels":[{"score":0,"label":"未评估/无有效观察","description":"没有足够有效证据；不得当作能力失败或0分技术表现"},{"score":1,"label":"依赖持续提示","description":"只能在持续口头/动作提示下完成，或表现不稳定；安全风险需单独记录"},{"score":2,"label":"部分达到","description":"能完成部分关键环节，但在标准条件下仍需间歇提示或出现明显不稳定"},{"score":3,"label":"标准条件下独立稳定","description":"在约定标准条件下无需提示，能独立完成该能力的主要判据"},{"score":4,"label":"变化/对抗条件下稳定应用","description":"面对合理变化或对抗压力仍能作出合适选择并保持执行质量"}],"note":"描述性锚点草案；教练试测后校准。评分不直接触发晋级。"}', updated_at=CURRENT_TIMESTAMP WHERE id='AC-S1-SERVE';
UPDATE assessment_criteria SET test_protocol_json='{"protocolVersion":"pilot-v1","station":"正反手基础控制站","purpose":"观察正反手在可控来球下的准备、击球点、方向控制和回位","setup":"底线附近设置可重复喂球位置；正手与反手分别测试；标记目标区域但不预设通过比例","procedure":["观察者说明目标区域和安全边界","喂球者交替向正反手可处理区域送球","学员完成击球并恢复准备位置；随后增加轻微方向变化"],"valid_trial":"来球处于预先约定的可处理范围；明显偏离或喂球失误单独记录，不纳入技术执行观察","record_fields":["准备姿势与握拍调整","击球点与身体平衡","拍面控制与球路方向","回球深度/高度","击球后恢复位置"],"safety_stop":"移动失衡、疼痛或连续疲劳时停止并调整喂球","adaptations":"根据身高、年龄和移动能力调整喂球速度/距离；记录具体设置，避免把喂球难度差异误判为技术差异","pilot":"比较固定喂球与轻微变化喂球下的表现，检查评分锚点能否区分动作完成与独立控制","trialCount":"由教练试测校准后确定","passThreshold":null,"decisionRule":"本协议为试测稿；不得据此自动晋级"}', rubric_json='{"scale":"0-4","levels":[{"score":0,"label":"未评估/无有效观察","description":"没有足够有效证据；不得当作能力失败或0分技术表现"},{"score":1,"label":"依赖持续提示","description":"只能在持续口头/动作提示下完成，或表现不稳定；安全风险需单独记录"},{"score":2,"label":"部分达到","description":"能完成部分关键环节，但在标准条件下仍需间歇提示或出现明显不稳定"},{"score":3,"label":"标准条件下独立稳定","description":"在约定标准条件下无需提示，能独立完成该能力的主要判据"},{"score":4,"label":"变化/对抗条件下稳定应用","description":"面对合理变化或对抗压力仍能作出合适选择并保持执行质量"}],"note":"描述性锚点草案；教练试测后校准。评分不直接触发晋级。"}', updated_at=CURRENT_TIMESTAMP WHERE id='AC-S1-GROUND';
UPDATE assessment_criteria SET test_protocol_json='{"protocolVersion":"pilot-v1","station":"第三拍 Drop 情境站","purpose":"观察学员能否从底线第三拍情境将球以可控弧线送入对方非截击区附近，为上网创造条件","setup":"双打场地；对侧两名观察/接球者站在NVZ附近；使用一致的发球与接发启动流程","procedure":["从发球方底线开始，由测试者完成发球和接发","学员在第三拍位置处理回球，尝试drop并按战术前移","接球者以约定方式反馈球是否迫使其在NVZ附近击球；记录球路与下一步站位"],"valid_trial":"发球、接发和第二拍均形成可处理的第三拍；明显失控的前序球应标注为流程无效，不把责任归给第三拍执行","record_fields":["第三拍击球位置与身体平衡","球弧线/过网高度观察","落点与对方击球位置","是否给己方创造前移机会","击球后移动与队形"],"safety_stop":"避免强行追赶明显不可处理球；出现疼痛或滑步风险即停","adaptations":"初次测试可用较稳定接发喂球建立标准条件，再增加接发落点变化；不同条件分开记录","pilot":"由教练先定义可处理接发范围，使用录像复核球弧线与落点判断；试测后校准有效情境和重复次数","trialCount":"由教练试测校准后确定","passThreshold":null,"decisionRule":"本协议为试测稿；不得据此自动晋级"}', rubric_json='{"scale":"0-4","levels":[{"score":0,"label":"未评估/无有效观察","description":"没有足够有效证据；不得当作能力失败或0分技术表现"},{"score":1,"label":"依赖持续提示","description":"只能在持续口头/动作提示下完成，或表现不稳定；安全风险需单独记录"},{"score":2,"label":"部分达到","description":"能完成部分关键环节，但在标准条件下仍需间歇提示或出现明显不稳定"},{"score":3,"label":"标准条件下独立稳定","description":"在约定标准条件下无需提示，能独立完成该能力的主要判据"},{"score":4,"label":"变化/对抗条件下稳定应用","description":"面对合理变化或对抗压力仍能作出合适选择并保持执行质量"}],"note":"描述性锚点草案；教练试测后校准。评分不直接触发晋级。"}', updated_at=CURRENT_TIMESTAMP WHERE id='AC-S1-DROP';
UPDATE assessment_criteria SET test_protocol_json='{"protocolVersion":"pilot-v1","station":"NVZ 基础 Dink 相持站","purpose":"观察在NVZ线后能否以安全站位完成可控dink并维持合作相持","setup":"双方位于NVZ附近；使用合作性连续相持，不以对手失误作为唯一结果","procedure":["先进行直线合作dink","再进行斜线合作dink","观察者在不突然加速的前提下改变落点，观察学员调整步伐、拍面和回位"],"valid_trial":"来球可被正常触及且双方按合作任务进行；对方明显失误或外部干扰时记录中断原因","record_fields":["是否保持在NVZ线后完成截击规则","准备姿势与拍头位置","击球高度、弧线和落点控制","小幅移动后的平衡与回位","连续相持中的非受迫失误类型"],"safety_stop":"禁止为救球踩入NVZ内截击；失衡、碰撞风险或不适时停止","adaptations":"可缩短合作相持距离或降低节奏以适配初学/年长学员；记录球速和站位距离，不能与标准组直接比较","pilot":"比较不同教练对NVZ犯规、可控球和非受迫失误的判读一致性；先校准观察定义","trialCount":"由教练试测校准后确定","passThreshold":null,"decisionRule":"本协议为试测稿；不得据此自动晋级"}', rubric_json='{"scale":"0-4","levels":[{"score":0,"label":"未评估/无有效观察","description":"没有足够有效证据；不得当作能力失败或0分技术表现"},{"score":1,"label":"依赖持续提示","description":"只能在持续口头/动作提示下完成，或表现不稳定；安全风险需单独记录"},{"score":2,"label":"部分达到","description":"能完成部分关键环节，但在标准条件下仍需间歇提示或出现明显不稳定"},{"score":3,"label":"标准条件下独立稳定","description":"在约定标准条件下无需提示，能独立完成该能力的主要判据"},{"score":4,"label":"变化/对抗条件下稳定应用","description":"面对合理变化或对抗压力仍能作出合适选择并保持执行质量"}],"note":"描述性锚点草案；教练试测后校准。评分不直接触发晋级。"}', updated_at=CURRENT_TIMESTAMP WHERE id='AC-S1-DINK';
UPDATE assessment_criteria SET test_protocol_json='{"protocolVersion":"pilot-v1","station":"规则与安全情境站","purpose":"确认学员理解并能在实际情境中应用两跳规则、发球规则、NVZ规则和基本安全行为","setup":"准备规则口头问答卡与场上情境演示；使用当前适用的官方规则版本并记录版本日期","procedure":["请学员解释发球和接发后两跳规则","演示NVZ内外击球与动量带入情境","呈现边线/底线和发球区情境，让学员判断","观察双打沟通、避让和停止危险回合的行为"],"valid_trial":"题意和情境表达清晰；如学员未听清或场景设置不完整，应重新说明并记录，不直接判错","record_fields":["两跳规则解释与应用","发球动作合法性理解","NVZ规则与动量规则","界内/界外判断依据","沟通、避让和安全停止行为"],"safety_stop":"不得用真实碰撞或危险动作制造测试情境","adaptations":"可用口头、图示或现场演示多种表达方式；语言表达困难不等于规则理解不足，需记录采用的方式","pilot":"两位教练按同一题卡独立评分，检查问题措辞和规则答案是否唯一、无歧义","trialCount":"由教练试测校准后确定","passThreshold":null,"decisionRule":"本协议为试测稿；不得据此自动晋级"}', rubric_json='{"scale":"0-4","levels":[{"score":0,"label":"未评估/无有效观察","description":"没有足够有效证据；不得当作能力失败或0分技术表现"},{"score":1,"label":"依赖持续提示","description":"只能在持续口头/动作提示下完成，或表现不稳定；安全风险需单独记录"},{"score":2,"label":"部分达到","description":"能完成部分关键环节，但在标准条件下仍需间歇提示或出现明显不稳定"},{"score":3,"label":"标准条件下独立稳定","description":"在约定标准条件下无需提示，能独立完成该能力的主要判据"},{"score":4,"label":"变化/对抗条件下稳定应用","description":"面对合理变化或对抗压力仍能作出合适选择并保持执行质量"}],"note":"描述性锚点草案；教练试测后校准。评分不直接触发晋级。"}', updated_at=CURRENT_TIMESTAMP WHERE id='AC-S1-RULE';
UPDATE assessment_criteria SET test_protocol_json='{"protocolVersion":"pilot-v1","station":"基本移动与回位站","purpose":"观察分腿垫步、启动、短距离移动、制动和回到准备位置的安全性","setup":"使用场地内短距离标志点；不以极限冲刺或折返计时作为初阶门槛","procedure":["学员从准备姿势开始，根据教练左右/前后口令移动","完成触点或模拟击球动作后制动","回到平衡准备位置，左右方向交替进行"],"valid_trial":"口令清晰且移动路径无障碍；外部干扰或标志点移动时重做并注明","record_fields":["分腿垫步时机","第一步启动方向","重心与步幅控制","制动时身体平衡","回位与下一拍准备"],"safety_stop":"出现疼痛、明显失衡或呼吸不适立即停止；不要求最大速度","adaptations":"按年龄、关节活动和训练经验调整移动距离与节奏；不做医疗判断；调整条件单独记录","pilot":"先检查不同身高/年龄学员是否都能安全完成任务，再确定分组条件与评分描述","trialCount":"由教练试测校准后确定","passThreshold":null,"decisionRule":"本协议为试测稿；不得据此自动晋级"}', rubric_json='{"scale":"0-4","levels":[{"score":0,"label":"未评估/无有效观察","description":"没有足够有效证据；不得当作能力失败或0分技术表现"},{"score":1,"label":"依赖持续提示","description":"只能在持续口头/动作提示下完成，或表现不稳定；安全风险需单独记录"},{"score":2,"label":"部分达到","description":"能完成部分关键环节，但在标准条件下仍需间歇提示或出现明显不稳定"},{"score":3,"label":"标准条件下独立稳定","description":"在约定标准条件下无需提示，能独立完成该能力的主要判据"},{"score":4,"label":"变化/对抗条件下稳定应用","description":"面对合理变化或对抗压力仍能作出合适选择并保持执行质量"}],"note":"描述性锚点草案；教练试测后校准。评分不直接触发晋级。"}', updated_at=CURRENT_TIMESTAMP WHERE id='AC-S1-MOVE';
UPDATE assessment_criteria SET test_protocol_json='{"protocolVersion":"pilot-v1","station":"第三拍选择决策站","purpose":"观察学员能否根据接发落点、来球高度/速度和自身位置选择drop、drive或drip等第三拍方案","setup":"设置可重复的多种接发情境，测试者预先定义各情境意图；不向学员提前透露每球答案","procedure":["测试者发球，对方按预设但随机顺序送出不同接发质量","学员判断并执行第三拍方案","观察者记录选择依据、执行质量及下一拍是否形成合理过渡"],"valid_trial":"前两拍形成预设可判断情境；喂球偏差导致决策条件不成立时标为无效，不以结果倒推选择错误","record_fields":["来球高度、深度、速度和方向","学员所选方案","选择是否与情境匹配","击球质量与风险控制","第三拍后站位/下一拍准备"],"safety_stop":"不以高速连续喂球制造疲劳；出现疼痛或失衡停止","adaptations":"可先做清晰对比情境，再逐渐混合；适配时记录情境难度，避免不同版本混算","pilot":"教练先共同制定情境分类和合理选项范围；录像复核“决策错误”与“执行失误”是否被正确区分","trialCount":"由教练试测校准后确定","passThreshold":null,"decisionRule":"本协议为试测稿；不得据此自动晋级"}', rubric_json='{"scale":"0-4","levels":[{"score":0,"label":"未评估/无有效观察","description":"没有足够有效证据；不得当作能力失败或0分技术表现"},{"score":1,"label":"依赖持续提示","description":"只能在持续口头/动作提示下完成，或表现不稳定；安全风险需单独记录"},{"score":2,"label":"部分达到","description":"能完成部分关键环节，但在标准条件下仍需间歇提示或出现明显不稳定"},{"score":3,"label":"标准条件下独立稳定","description":"在约定标准条件下无需提示，能独立完成该能力的主要判据"},{"score":4,"label":"变化/对抗条件下稳定应用","description":"面对合理变化或对抗压力仍能作出合适选择并保持执行质量"}],"note":"描述性锚点草案；教练试测后校准。评分不直接触发晋级。"}', updated_at=CURRENT_TIMESTAMP WHERE id='AC-S2-CHOICE';
UPDATE assessment_criteria SET test_protocol_json='{"protocolVersion":"pilot-v1","station":"过渡区 Reset 连续防守站","purpose":"观察在底线至NVZ过渡区面对压力球时，能否用稳定拍面和合适球路重置回合","setup":"学员从过渡区开始；对侧以预设中等压力球喂球；区分正手、反手和脚边球","procedure":["学员在过渡区准备，喂球者向身体两侧及脚边送球","学员用block、drop或half-volley reset化解压力","根据回球质量继续下一拍，不因单次成功立即结束观察"],"valid_trial":"来球处于预设可处理范围；明显过快/过偏球单独标记，不与标准喂球表现混合","record_fields":["准备姿势与拍头位置","拍面稳定和触球点","回球高度/深度与对手压迫程度","是否避免无谓提速","击球后平衡与继续移动"],"safety_stop":"控制喂球强度，避免脚踝/膝部高风险急停；任何疼痛即停","adaptations":"初阶中阶衔接者先从较慢喂球开始；高级组增加落点变化但单独标记难度","pilot":"定义“成功reset”是回到可继续相持的中性球而非单纯过网；教练共同看片校准","trialCount":"由教练试测校准后确定","passThreshold":null,"decisionRule":"本协议为试测稿；不得据此自动晋级"}', rubric_json='{"scale":"0-4","levels":[{"score":0,"label":"未评估/无有效观察","description":"没有足够有效证据；不得当作能力失败或0分技术表现"},{"score":1,"label":"依赖持续提示","description":"只能在持续口头/动作提示下完成，或表现不稳定；安全风险需单独记录"},{"score":2,"label":"部分达到","description":"能完成部分关键环节，但在标准条件下仍需间歇提示或出现明显不稳定"},{"score":3,"label":"标准条件下独立稳定","description":"在约定标准条件下无需提示，能独立完成该能力的主要判据"},{"score":4,"label":"变化/对抗条件下稳定应用","description":"面对合理变化或对抗压力仍能作出合适选择并保持执行质量"}],"note":"描述性锚点草案；教练试测后校准。评分不直接触发晋级。"}', updated_at=CURRENT_TIMESTAMP WHERE id='AC-S2-RESET';
UPDATE assessment_criteria SET test_protocol_json='{"protocolVersion":"pilot-v1","station":"长短 Dink 与节奏变化站","purpose":"观察能否在长短落点、方向和节奏变化中维持NVZ控制与回位","setup":"双方位于NVZ；在场地标出长/短目标区域，仅用于观察落点，不先设通过百分比","procedure":["进行合作直线与斜线dink","教练按随机顺序提示深/短落点","在可控节奏下加入轻微旋转或速度变化，观察学员是否调整拍面和站位"],"valid_trial":"提示明确且来球可处理；喂球者明显偏离目标时记录为喂球无效","record_fields":["目标识别","深浅和方向控制","节奏/旋转变化的质量","对变化球的准备调整","击球后平衡和回位"],"safety_stop":"不突然加速至危险hands battle；保持合作任务可控","adaptations":"旋转与节奏变化按学员基础逐步引入；若某项未教过，标记未教学/不适用，不记为失败","pilot":"校准长短区域定义、旋转观察语言及不同教练对“控制成功”的一致性","trialCount":"由教练试测校准后确定","passThreshold":null,"decisionRule":"本协议为试测稿；不得据此自动晋级"}', rubric_json='{"scale":"0-4","levels":[{"score":0,"label":"未评估/无有效观察","description":"没有足够有效证据；不得当作能力失败或0分技术表现"},{"score":1,"label":"依赖持续提示","description":"只能在持续口头/动作提示下完成，或表现不稳定；安全风险需单独记录"},{"score":2,"label":"部分达到","description":"能完成部分关键环节，但在标准条件下仍需间歇提示或出现明显不稳定"},{"score":3,"label":"标准条件下独立稳定","description":"在约定标准条件下无需提示，能独立完成该能力的主要判据"},{"score":4,"label":"变化/对抗条件下稳定应用","description":"面对合理变化或对抗压力仍能作出合适选择并保持执行质量"}],"note":"描述性锚点草案；教练试测后校准。评分不直接触发晋级。"}', updated_at=CURRENT_TIMESTAMP WHERE id='AC-S2-DINK';
UPDATE assessment_criteria SET test_protocol_json='{"protocolVersion":"pilot-v1","station":"网前截击选择站","purpose":"观察面对不同高度、速度和身体方向的来球，能否选择block、punch、flick或roll等合适处理方式","setup":"学员处于NVZ线后准备姿势；喂球者控制来球高度、速度和方向，避免身体危险球","procedure":["先以低压来球确认拍面控制","再随机提供可截击球、需缓冲球和可进攻球","学员自主选择处理方式，观察是否控制风险与回位"],"valid_trial":"来球落在预设安全可处理区域；过近身体或明显失控来球标记无效/安全停止","record_fields":["识别来球高度与速度","选择的截击类型及理由","拍面/挥拍幅度控制","球路目标与风险","击球后恢复与搭档协同"],"safety_stop":"不得喂向头面部或近距离身体；保持安全距离和可控速度","adaptations":"从block/punch基础开始，flick/roll仅在已教学且身体条件适宜时观察；未教学项标记未评估","pilot":"两名教练先对各类来球定义合理选项范围，防止将个人风格偏好误判为错误","trialCount":"由教练试测校准后确定","passThreshold":null,"decisionRule":"本协议为试测稿；不得据此自动晋级"}', rubric_json='{"scale":"0-4","levels":[{"score":0,"label":"未评估/无有效观察","description":"没有足够有效证据；不得当作能力失败或0分技术表现"},{"score":1,"label":"依赖持续提示","description":"只能在持续口头/动作提示下完成，或表现不稳定；安全风险需单独记录"},{"score":2,"label":"部分达到","description":"能完成部分关键环节，但在标准条件下仍需间歇提示或出现明显不稳定"},{"score":3,"label":"标准条件下独立稳定","description":"在约定标准条件下无需提示，能独立完成该能力的主要判据"},{"score":4,"label":"变化/对抗条件下稳定应用","description":"面对合理变化或对抗压力仍能作出合适选择并保持执行质量"}],"note":"描述性锚点草案；教练试测后校准。评分不直接触发晋级。"}', updated_at=CURRENT_TIMESTAMP WHERE id='AC-S2-VOLLEY';
UPDATE assessment_criteria SET test_protocol_json='{"protocolVersion":"pilot-v1","station":"Lob / Overhead / Bounce-it 判断站","purpose":"观察学员能否识别高球、判断是否进攻或让球，并安全完成overhead或bounce-it","setup":"在场地上方安全空间足够的条件下进行；先用可控高球，逐渐加入落点变化","procedure":["教练喂出不同深度和方向的高球","学员口头或动作表达是否进攻/让球","对可安全处理球执行overhead；对不利球执行bounce-it或防守站位"],"valid_trial":"高球轨迹清晰且有足够安全处理空间；场地受限或球落点不可判断时标记无效","record_fields":["高球轨迹与落点判断","是否正确选择进攻/让球","移动路线与搭档沟通","overhead击球控制","bounce-it后的回合准备"],"safety_stop":"检查顶棚、灯具、周边人员；禁止向相邻场地追球；出现碰撞风险即停","adaptations":"未教学overhead或身体条件不适宜者只观察判断和安全让球，不把未教学动作记为失败","pilot":"验证高球情境难度分级，确认场地安全条件和教练对可进攻球的判断一致","trialCount":"由教练试测校准后确定","passThreshold":null,"decisionRule":"本协议为试测稿；不得据此自动晋级"}', rubric_json='{"scale":"0-4","levels":[{"score":0,"label":"未评估/无有效观察","description":"没有足够有效证据；不得当作能力失败或0分技术表现"},{"score":1,"label":"依赖持续提示","description":"只能在持续口头/动作提示下完成，或表现不稳定；安全风险需单独记录"},{"score":2,"label":"部分达到","description":"能完成部分关键环节，但在标准条件下仍需间歇提示或出现明显不稳定"},{"score":3,"label":"标准条件下独立稳定","description":"在约定标准条件下无需提示，能独立完成该能力的主要判据"},{"score":4,"label":"变化/对抗条件下稳定应用","description":"面对合理变化或对抗压力仍能作出合适选择并保持执行质量"}],"note":"描述性锚点草案；教练试测后校准。评分不直接触发晋级。"}', updated_at=CURRENT_TIMESTAMP WHERE id='AC-S2-LOB';
UPDATE assessment_criteria SET test_protocol_json='{"protocolVersion":"pilot-v1","station":"双打站位与轮转站","purpose":"观察stacking、沟通、覆盖分工和攻防转换中的轮转是否合理","setup":"四人双打；指定搭档；记录左右手持拍、站位起点和是否采用stacking","procedure":["从发球/接发站位开始，完成若干完整回合观察","安排需要换位或覆盖中路的情境","教练暂停询问搭档沟通意图，再恢复开放回合"],"valid_trial":"四名参与者明确任务并按约定开始；搭档误解任务时先重新说明，不直接计作技术失败","record_fields":["发接发站位合法性","stacking执行时机","中路球沟通与责任分配","轮转后的场地覆盖","失位后的恢复与互相支持"],"safety_stop":"控制对抗强度，避免交叉冲撞；出现不适停止","adaptations":"初学双打者先做半场/定点轮转，再进入完整场地；记录是否使用提示","pilot":"使用同一场景脚本由不同教练观察，检查站位与责任分配的判读一致性","trialCount":"由教练试测校准后确定","passThreshold":null,"decisionRule":"本协议为试测稿；不得据此自动晋级"}', rubric_json='{"scale":"0-4","levels":[{"score":0,"label":"未评估/无有效观察","description":"没有足够有效证据；不得当作能力失败或0分技术表现"},{"score":1,"label":"依赖持续提示","description":"只能在持续口头/动作提示下完成，或表现不稳定；安全风险需单独记录"},{"score":2,"label":"部分达到","description":"能完成部分关键环节，但在标准条件下仍需间歇提示或出现明显不稳定"},{"score":3,"label":"标准条件下独立稳定","description":"在约定标准条件下无需提示，能独立完成该能力的主要判据"},{"score":4,"label":"变化/对抗条件下稳定应用","description":"面对合理变化或对抗压力仍能作出合适选择并保持执行质量"}],"note":"描述性锚点草案；教练试测后校准。评分不直接触发晋级。"}', updated_at=CURRENT_TIMESTAMP WHERE id='AC-S2-DOUBLES';
UPDATE assessment_criteria SET test_protocol_json='{"protocolVersion":"pilot-v1","station":"高阶发接发策略站","purpose":"观察学员是否根据比分、对手站位和自身优势调整发球/接发目标，并为第三拍建立条件","setup":"双打实战站位；记录比分情境、对手特征和目标策略；使用多种但可控的接发/发球任务","procedure":["设置不同比分与对手站位情境","学员先说明或选择目标，再执行发球/接发","观察下一拍衔接及是否根据对手反馈调整策略"],"valid_trial":"比分和对手情境已明确；喂球失误或对手未按脚本站位时注明并重做","record_fields":["目标选择及情境依据","发球/接发落点和质量","是否限制对手第三拍选项","第三拍衔接","根据反馈调整策略的能力"],"safety_stop":"保持真实比赛强度但避免疲劳性连续极限发球","adaptations":"可根据竞技路线设置不同对手风格；必须记录对手水平和脚本，避免直接横向比较","pilot":"教练共同定义策略合理性观察表，避免仅以赢分/输分倒推策略质量","trialCount":"由教练试测校准后确定","passThreshold":null,"decisionRule":"本协议为试测稿；不得据此自动晋级"}', rubric_json='{"scale":"0-4","levels":[{"score":0,"label":"未评估/无有效观察","description":"没有足够有效证据；不得当作能力失败或0分技术表现"},{"score":1,"label":"依赖持续提示","description":"只能在持续口头/动作提示下完成，或表现不稳定；安全风险需单独记录"},{"score":2,"label":"部分达到","description":"能完成部分关键环节，但在标准条件下仍需间歇提示或出现明显不稳定"},{"score":3,"label":"标准条件下独立稳定","description":"在约定标准条件下无需提示，能独立完成该能力的主要判据"},{"score":4,"label":"变化/对抗条件下稳定应用","description":"面对合理变化或对抗压力仍能作出合适选择并保持执行质量"}],"note":"描述性锚点草案；教练试测后校准。评分不直接触发晋级。"}', updated_at=CURRENT_TIMESTAMP WHERE id='AC-S3-SERVE';
UPDATE assessment_criteria SET test_protocol_json='{"protocolVersion":"pilot-v1","station":"第三拍至第五拍连续决策站","purpose":"观察从发接发到第三、第五拍的连续判断、技术选择和位置衔接","setup":"四人双打；按情境安排不同接发深度、速度与落点；对方采用约定防守策略","procedure":["开始完整发接发回合","学员在第三拍自主选择drop、drive或其他已教学方案","根据第四拍反馈完成第五拍选择并继续回合","记录决策链而非只看最终得失分"],"valid_trial":"前序球符合预设情境；因喂球偏差导致决策窗口消失时单独标记","record_fields":["第三拍情境识别与选择","第三拍执行质量","第四拍反馈识别","第五拍选择与执行","连续决策后的站位和协同"],"safety_stop":"对抗强度逐级增加，保持回合间恢复；出现疼痛或过度疲劳停止","adaptations":"可按对手水平调整防守压力；不同压力等级分别记录","pilot":"录像标注每一拍的情境和选择，检查教练是否能稳定区分决策质量与击球结果","trialCount":"由教练试测校准后确定","passThreshold":null,"decisionRule":"本协议为试测稿；不得据此自动晋级"}', rubric_json='{"scale":"0-4","levels":[{"score":0,"label":"未评估/无有效观察","description":"没有足够有效证据；不得当作能力失败或0分技术表现"},{"score":1,"label":"依赖持续提示","description":"只能在持续口头/动作提示下完成，或表现不稳定；安全风险需单独记录"},{"score":2,"label":"部分达到","description":"能完成部分关键环节，但在标准条件下仍需间歇提示或出现明显不稳定"},{"score":3,"label":"标准条件下独立稳定","description":"在约定标准条件下无需提示，能独立完成该能力的主要判据"},{"score":4,"label":"变化/对抗条件下稳定应用","description":"面对合理变化或对抗压力仍能作出合适选择并保持执行质量"}],"note":"描述性锚点草案；教练试测后校准。评分不直接触发晋级。"}', updated_at=CURRENT_TIMESTAMP WHERE id='AC-S3-THIRD';
UPDATE assessment_criteria SET test_protocol_json='{"protocolVersion":"pilot-v1","station":"NVZ 节奏、旋转与可攻球识别站","purpose":"观察学员能否控制相持节奏、改变球路并识别真正可攻击的球","setup":"双方在NVZ线附近；先合作相持，再转入半开放相持；确保双方知晓安全边界","procedure":["进行合作dink建立基线","学员主动改变深度、角度或节奏","对方随机提供高/浅/中性球，学员判断继续控制、提速或转换方向","观察提速后的下一拍准备"],"valid_trial":"来球具备可判断的高度和位置；明显非受迫喂球失误标记无效","record_fields":["节奏变化是否有目的","旋转/弧线与落点控制","可攻球识别依据","提速时机与目标","提速后是否准备counter"],"safety_stop":"避免无预警近距离全力击球；控制对练者安全距离","adaptations":"根据对练者能力控制提速幅度；无法稳定提供相同压力时记录为探索性观察","pilot":"教练使用录像共同标记可攻球与非可攻球情境，形成一致的观察案例库","trialCount":"由教练试测校准后确定","passThreshold":null,"decisionRule":"本协议为试测稿；不得据此自动晋级"}', rubric_json='{"scale":"0-4","levels":[{"score":0,"label":"未评估/无有效观察","description":"没有足够有效证据；不得当作能力失败或0分技术表现"},{"score":1,"label":"依赖持续提示","description":"只能在持续口头/动作提示下完成，或表现不稳定；安全风险需单独记录"},{"score":2,"label":"部分达到","description":"能完成部分关键环节，但在标准条件下仍需间歇提示或出现明显不稳定"},{"score":3,"label":"标准条件下独立稳定","description":"在约定标准条件下无需提示，能独立完成该能力的主要判据"},{"score":4,"label":"变化/对抗条件下稳定应用","description":"面对合理变化或对抗压力仍能作出合适选择并保持执行质量"}],"note":"描述性锚点草案；教练试测后校准。评分不直接触发晋级。"}', updated_at=CURRENT_TIMESTAMP WHERE id='AC-S3-NVZ';
UPDATE assessment_criteria SET test_protocol_json='{"protocolVersion":"pilot-v1","station":"过渡区防守到反攻转换站","purpose":"观察在连续压力下能否先稳定重置，再识别机会并安全转入进攻","setup":"学员从过渡区开始；对侧交替施加深球、脚边球和中速截击压力","procedure":["学员先完成防守reset","当回球质量改善时判断是否前移或转入进攻","继续完成开放回合，观察从防守到进攻的时机与位置","记录过早提速和被动回球"],"valid_trial":"喂球压力符合预设等级；明显失控球标记为非标准情境","record_fields":["防守准备与reset质量","是否维持中性球","进攻机会识别","转换时机与移动路线","转换后队形与回合控制"],"safety_stop":"不以极限低身位和急停作为要求；出现疼痛、失衡即停止","adaptations":"按学员身体能力调整喂球速度和连续回合长度；记录压力等级","pilot":"建立防守成功、可转攻机会的情境例子，统一教练对转换时机的判断","trialCount":"由教练试测校准后确定","passThreshold":null,"decisionRule":"本协议为试测稿；不得据此自动晋级"}', rubric_json='{"scale":"0-4","levels":[{"score":0,"label":"未评估/无有效观察","description":"没有足够有效证据；不得当作能力失败或0分技术表现"},{"score":1,"label":"依赖持续提示","description":"只能在持续口头/动作提示下完成，或表现不稳定；安全风险需单独记录"},{"score":2,"label":"部分达到","description":"能完成部分关键环节，但在标准条件下仍需间歇提示或出现明显不稳定"},{"score":3,"label":"标准条件下独立稳定","description":"在约定标准条件下无需提示，能独立完成该能力的主要判据"},{"score":4,"label":"变化/对抗条件下稳定应用","description":"面对合理变化或对抗压力仍能作出合适选择并保持执行质量"}],"note":"描述性锚点草案；教练试测后校准。评分不直接触发晋级。"}', updated_at=CURRENT_TIMESTAMP WHERE id='AC-S3-TRANSITION';
UPDATE assessment_criteria SET test_protocol_json='{"protocolVersion":"pilot-v1","station":"Hands Battle 与 Counter 站","purpose":"观察网前快速交换中的准备、拍面稳定、反应选择和风险控制","setup":"双方保持安全间距；从中等速度开始，明确击球区域和禁止瞄准身体的规则","procedure":["先进行可控的短促截击交换","逐步增加方向和节奏变化","加入对手提速情境，学员自主选择block、counter或控制回球","观察每次击球后的准备恢复"],"valid_trial":"球速和距离在约定安全范围；过近身体或失控球立即判定安全中止，不记为技术失败","record_fields":["预备姿势和拍头位置","拍面稳定与触球点","是否选择合理counter或缓冲","目标控制和风险管理","击球后是否快速恢复"],"safety_stop":"禁止近距离瞄准头面部/身体；一旦出现危险速度或碰撞风险立即停止","adaptations":"根据经验从合作喂球到开放交换渐进；未达到安全条件不进行高速度测试","pilot":"教练共同定义安全球速范围和可接受counter选择，先校准安全标准再观察竞技表现","trialCount":"由教练试测校准后确定","passThreshold":null,"decisionRule":"本协议为试测稿；不得据此自动晋级"}', rubric_json='{"scale":"0-4","levels":[{"score":0,"label":"未评估/无有效观察","description":"没有足够有效证据；不得当作能力失败或0分技术表现"},{"score":1,"label":"依赖持续提示","description":"只能在持续口头/动作提示下完成，或表现不稳定；安全风险需单独记录"},{"score":2,"label":"部分达到","description":"能完成部分关键环节，但在标准条件下仍需间歇提示或出现明显不稳定"},{"score":3,"label":"标准条件下独立稳定","description":"在约定标准条件下无需提示，能独立完成该能力的主要判据"},{"score":4,"label":"变化/对抗条件下稳定应用","description":"面对合理变化或对抗压力仍能作出合适选择并保持执行质量"}],"note":"描述性锚点草案；教练试测后校准。评分不直接触发晋级。"}', updated_at=CURRENT_TIMESTAMP WHERE id='AC-S3-HANDS';
UPDATE assessment_criteria SET test_protocol_json='{"protocolVersion":"pilot-v1","station":"高阶双打适应与比分管理站","purpose":"观察学员能否与搭档协同，根据比分和对手特点调整发接发、落点和攻防策略","setup":"四人双打；记录搭档、对手水平、左右手、场地条件和比分脚本","procedure":["安排不同比分阶段的开局与关键分情境","要求学员与搭档沟通一个战术目标","进行开放回合，观察是否执行并根据对手反应调整","回合后简短复盘选择依据"],"valid_trial":"比分、角色和战术任务明确；对手偏离情境时标记并重新设定","record_fields":["搭档沟通与角色分工","发接发战术选择","针对对手弱点的调整","关键分风险管理","战术执行后的复盘与修正"],"safety_stop":"保持竞赛强度但遵守休息与补水；出现疼痛或异常疲劳停止","adaptations":"按对手水平与比赛经验分层；记录搭档与对手背景，避免把搭档能力误算为个人能力","pilot":"跨不同搭档重复观察，识别个人决策与搭档配合的影响；通过录像校准评分","trialCount":"由教练试测校准后确定","passThreshold":null,"decisionRule":"本协议为试测稿；不得据此自动晋级"}', rubric_json='{"scale":"0-4","levels":[{"score":0,"label":"未评估/无有效观察","description":"没有足够有效证据；不得当作能力失败或0分技术表现"},{"score":1,"label":"依赖持续提示","description":"只能在持续口头/动作提示下完成，或表现不稳定；安全风险需单独记录"},{"score":2,"label":"部分达到","description":"能完成部分关键环节，但在标准条件下仍需间歇提示或出现明显不稳定"},{"score":3,"label":"标准条件下独立稳定","description":"在约定标准条件下无需提示，能独立完成该能力的主要判据"},{"score":4,"label":"变化/对抗条件下稳定应用","description":"面对合理变化或对抗压力仍能作出合适选择并保持执行质量"}],"note":"描述性锚点草案；教练试测后校准。评分不直接触发晋级。"}', updated_at=CURRENT_TIMESTAMP WHERE id='AC-S3-DOUBLES';
UPDATE assessment_protocols SET conditions_json='{"standardCourt":"标准匹克球双打场地；如使用其他场地需记录尺寸和差异","equipment":"同一测试批次尽量使用同型号球拍和球；记录球型号、磨损状态","warmup":"测试前完成统一、适龄的动态热身；热身内容与时长写入记录","feed":"记录喂球者、站位、喂球方式、速度等级和目标区域","environment":"记录日期、场地、室内/室外、风况/温度（适用时）","rest":"测试站之间安排恢复；不得用疲劳累积制造难度","recording":"每项记录有效观察、无效观察及原因；可录像时注明机位并取得必要同意","adaptation":"任何年龄、身体能力或经验适配均记录具体改变；适配条件的结果不与标准条件直接合并","safety":"测试前询问当日是否适宜训练；疼痛、头晕、异常疲劳、碰撞风险或场地不安全时立即停止","scoring":"按能力项描述性0–4锚点评分；未观察/无效观察记为未评估，不计0分","calibration":"试测阶段至少安排教练共同观察和复核；不得自动形成晋级结论","stageSpecific":"详见本协议各能力项测试卡","pilotStatus":"仅供教练试测，试次数和通过规则待验证","versionNote":"任何测试条件变化均需保留记录"}', updated_at=CURRENT_TIMESTAMP WHERE id='AP-STAGE1-V1';
